**一、网络：以太网 MAC + TCP/IP**

```verilog
// 以太网 MAC 寄存器
reg [47:0] mac_addr;        // MAC 地址
reg [15:0] eth_tx_len;      // 发送长度
reg [7:0] eth_tx_buf [0:2047]; // 发送缓冲
reg [7:0] eth_rx_buf [0:2047]; // 接收缓冲
reg eth_tx_start, eth_rx_ready;

// PHY 接口：MII（4 位数据）
reg [3:0] mii_txd;
reg mii_txen, mii_txclk;
wire [3:0] mii_rxd;
wire mii_rxdv, mii_rxclk;

// 发送状态机
reg [1:0] tx_state;
reg [10:0] tx_idx;

always @(posedge clk) begin
    case (tx_state)
        0: if (eth_tx_start) begin
            tx_idx <= 0; tx_state <= 1;
        end
        1: begin
            mii_txd <= eth_tx_buf[tx_idx][3:0];
            mii_txen <= 1;
            tx_idx <= tx_idx + 1;
            if (tx_idx == eth_tx_len - 1)
                tx_state <= 2;
        end
        2: begin
            mii_txen <= 0;
            tx_state <= 0;
        end
    endcase
end
```

