**一、USB 控制器**

USB 1.1 主机控制器，支持键盘、鼠标、U 盘。

```verilog
// USB 寄存器
reg usb_tx_start, usb_rx_ready;
reg [7:0] usb_tx_data, usb_rx_data;
reg [3:0] usb_state;

// USB 物理层（简化：FS 全速 12Mbps）
reg usb_dp, usb_dm;
wire usb_dp_in, usb_dm_in;

// 状态机
always @(posedge clk) begin
    case (usb_state)
        0: begin // 空闲
            usb_dp <= 1; usb_dm <= 0;
            if (usb_tx_start) usb_state <= 1;
        end
        1: begin // 发送同步
            usb_dp <= 0; usb_dm <= 1;
            usb_state <= 2;
        end
        2: begin // 发送数据位
            // 按位发送 usb_tx_data
            usb_state <= 3;
        end
        3: begin // 结束
            usb_dp <= 1; usb_dm <= 0;
            usb_state <= 0;
        end
    endcase
end

// USB 设备枚举（软件实现）
// SYSCALL #40: usb_enumerate
// SYSCALL #41: usb_read
// SYSCALL #42: usb_write
```

