**二、音频：PWM 输出 + I2S 接口**

```verilog
// PWM 音频输出
reg [7:0] pwm_duty;
reg [7:0] pwm_cnt;
reg pwm_out;

always @(posedge clk) begin
    pwm_cnt <= pwm_cnt + 1;
    pwm_out <= (pwm_cnt < pwm_duty);
end

// I2S 接口（接外部 DAC）
reg i2s_bclk, i2s_lrclk, i2s_data;
reg [7:0] i2s_shift;
reg [3:0] i2s_bit_cnt;

always @(posedge clk) begin
    i2s_bclk <= ~i2s_bclk;
    if (i2s_bclk) begin
        if (i2s_bit_cnt == 0) begin
            i2s_lrclk <= ~i2s_lrclk;
            i2s_bit_cnt <= 8;
        end else begin
            i2s_data <= i2s_shift[7];
            i2s_shift <= {i2s_shift[6:0], 1'b0};
            i2s_bit_cnt <= i2s_bit_cnt - 1;
        end
    end
end

// 音频系统调用
// SYSCALL #50: audio_play
// SYSCALL #51: audio_record
// SYSCALL #52: audio_stop
```

