    assign uart_tx = uart_tx_reg;

    // ===== 中断控制器 =====
    reg [7:0] irq_mask;
    reg [7:0] irq_pending;

    // ===== 主循环 =====
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            led <= 0;
            // 初始化所有外设
        end else begin
            // 多核执行
            // ...

            // VGA 显示
            // ...

            // SD 卡控制
            // ...

            // 以太网收发
            // ...

            // USB 收发
            // ...

            // 音频输出
            pwm_cnt <= pwm_cnt + 1;

            // 摄像头采集
            if (cam_pclk) begin
                if (cam_hsync && cam_vsync) begin
                    cam_buf[cam_y * 320 + cam_x] <= cam_data;
                    if (cam_x == 319) begin
                        cam_x <= 0;
                        cam_y <= cam_y + 1;
                    end else begin
                        cam_x <= cam_x + 1;
                    end
                end
            end

            // UART 收发
            // ...
        end
    end
endmodule
