    'RET':    0x0C, 'PUSH':  0x0D, 'POP':   0x0E,
    'OUT':    0x0F, 'AND':   0x10, 'OR':    0x11,
    'XOR':    0x12, 'NOT':   0x13, 'SHL':   0x14,
    'SHR':    0x15, 'LOADR': 0x16, 'STORER':0x17,
    'LOAD':   0x18, 'STORE': 0x19, 'INC':   0x1A,
    'DEC':    0x1B, 'MUL':   0x26, 'DIV':   0x27,
    'MOD':    0x28, 'DMA':   0x29, 'TIMER': 0x2A,
    'SEI':    0x2D, 'CLI':   0x2E, 'SYSCALL':0x38,
    'IRET':   0x3A, 'HLT':   0x3D, 'CSRR':  0x3E,
    'CSRW':   0x3F,
}

# 解析寄存器名
def parse_reg(s):
    s = s.strip().upper()
    if s.startswith('R'):
        return int(s[1:]) & 0xF
    return 0

# 解析立即数
def parse_imm(s):
    s = s.strip()
    if s.startswith('#'):
        s = s[1:]
    if s.startswith('0x') or s.startswith('0X'):
        return int(s, 16) & 0xFF
    return int(s) & 0xFF

# 解析一行汇编
def parse_line(line, labels, pc):
    # 去掉注释
    line = re.sub(r';.*$', '', line).strip()
    if not line:
        return None

    # 标签
    if line.endswith(':'):
        label = line[:-1].strip()
        labels[label] = pc
        return None

    # 分割助记符和操作数
    parts = line.split(None, 1)
    mnemonic = parts[0].upper()
    operands = parts[1] if len(parts) > 1 else ''

    if mnemonic not in OPCODES:
        raise ValueError(f"未知指令: {mnemonic}")

    opcode = OPCODES[mnemonic]
    rd = 0; rs = 0; imm = 0

    # 解析操作数
    if operands:
        ops = [o.strip() for o in operands.split(',')]
        if mnemonic in ('HALT', 'RET', 'SEI', 'CLI', 'IRET', 'HLT'):
            pass
        elif mnemonic in ('JMP', 'JZ', 'JNZ', 'CALL'):
            # 标签或地址
            if ops[0] in labels:
                imm = labels[ops[0]]
            else:
                imm = parse_imm(ops[0])
        elif mnemonic in ('PUSH', 'POP', 'INC', 'DEC', 'NOT', 'OUT'):
            rd = parse_reg(ops[0])
        elif mnemonic in ('MOV', 'ADD', 'SUB', 'CMP', 'AND', 'OR', 'XOR',
                          'MUL', 'DIV', 'MOD', 'LOADR', 'STORER'):
            rd = parse_reg(ops[0])
            rs = parse_reg(ops[1]) if len(ops) > 1 else 0
        elif mnemonic in ('MOVI', 'ADDI', 'SUBI', 'SHL', 'SHR'):
            rd = parse_reg(ops[0])
            imm = parse_imm(ops[1]) if len(ops) > 1 else 0
        elif mnemonic in ('LOAD', 'STORE'):
            rd = parse_reg(ops[0])
            imm = parse_imm(ops[1]) if len(ops) > 1 else 0
        elif mnemonic == 'SYSCALL':
            imm = parse_imm(ops[0]) if ops else 0
        elif mnemonic == 'CSRR':
            rd = parse_reg(ops[0])
            imm = parse_imm(ops[1]) if len(ops) > 1 else 0
        elif mnemonic == 'CSRW':
            imm = parse_imm(ops[0])
            rs = parse_reg(ops[1]) if len(ops) > 1 else 0

    # 编码
    word = (opcode << 24) | (rd << 20) | (rs << 16) | (imm << 8)
    return word

# 主函数
def assemble(source):
    lines = source.strip().split('\n')
    labels = {}
    words = []

    # 第一遍：收集标签
    pc = 0
    for line in lines:
        line = re.sub(r';.*$', '', line).strip()
        if not line:
            continue
        if line.endswith(':'):
            labels[line[:-1].strip()] = pc
        else:
            pc += 1

    # 第二遍：生成机器码
    for line in lines:
        word = parse_line(line, labels, pc)
        if word is not None:
            words.append(word)

    return words

# 入口
if __name__ == '__main__':
    if len(sys.argv) < 2:
        print("用法: asm.py <源文件.s>")
        sys.exit(1)

    with open(sys.argv[1], 'r') as f:
        source = f.read()

    words = assemble(source)

    # 输出十六进制
    for w in words:
        print(f"{w:08X}")
```

**二、编译器（Python）**

把极简 C 子集编译成你的机器码。

```python
#!/usr/bin/env python3
# cc.py - 极简 C 编译器

import sys, re

# ===== 词法分析 =====
def tokenize(source):
    tokens = []
    for line in source.split('\n'):
        line = re.sub(r'//.*$', '', line).strip()
        if not line:
            continue
        # 分割 token
        for tok in re.findall(r'[a-zA-Z_]\w*|\d+|[-+*/=<>(){}\[\];,]', line):
            tokens.append(tok)
    return tokens

# ===== 语法分析 =====
class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def next(self):
        tok = self.peek()
        self.pos += 1
        return tok

    def expect(self, tok):
        t = self.next()
        if t != tok:
            raise ValueError(f"期望 {tok}，得到 {t}")
        return t

    def parse(self):
        """解析程序：函数定义列表"""
        funcs = []
        while self.peek():
            funcs.append(self.parse_function())
        return funcs

    def parse_function(self):
        """解析函数：int name(params) { body }"""
        self.expect('int')
        name = self.next()
        self.expect('(')
        params = []
        while self.peek() != ')':
            self.expect('int')
            params.append(self.next())
            if self.peek() == ',':
                self.next()
        self.expect(')')
        self.expect('{')
        body = self.parse_block()
        self.expect('}')
        return {'name': name, 'params': params, 'body': body}

    def parse_block(self):
        """解析语句块"""
        stmts = []
        while self.peek() != '}':
            stmts.append(self.parse_statement())
        return stmts

    def parse_statement(self):
        """解析单条语句"""
        tok = self.peek()
        if tok == 'int':
            self.next()
            name = self.next()
            self.expect('=')
            expr = self.parse_expr()
            self.expect(';')
            return ('decl', name, expr)
        elif tok == 'if':
            self.next()
            self.expect('(')
            cond = self.parse_expr()
            self.expect(')')
            self.expect('{')
            then = self.parse_block()
            self.expect('}')
            els = None
            if self.peek() == 'else':
                self.next()
                self.expect('{')
                els = self.parse_block()
                self.expect('}')
            return ('if', cond, then, els)
        elif tok == 'while':
            self.next()
            self.expect('(')
            cond = self.parse_expr()
            self.expect(')')
            self.expect('{')
            body = self.parse_block()
            self.expect('}')
            return ('while', cond, body)
        elif tok == 'return':
            self.next()
            expr = self.parse_expr()
            self.expect(';')
            return ('return', expr)
        else:
            # 赋值或函数调用
            name = self.next()
            if self.peek() == '=':
                self.next()
                expr = self.parse_expr()
                self.expect(';')
                return ('assign', name, expr)
            elif self.peek() == '(':
                self.next()
                args = []
                while self.peek() != ')':
                    args.append(self.parse_expr())
                    if self.peek() == ',':
                        self.next()
                self.expect(')')
                self.expect(';')
                return ('call', name, args)
            else:
                raise ValueError(f"未知语句: {name}")

    def parse_expr(self):
        """解析表达式（简化：只处理二元运算）"""
        left = self.parse_term()
        while self.peek() in ('+', '-', '*', '/', '<', '>', '==', '!='):
            op = self.next()
            right = self.parse_term()
            left = ('binop', op, left, right)
        return left

    def parse_term(self):
        """解析项"""
        tok = self.next()
        if tok is None:
            raise ValueError("表达式意外结束")
        if tok.isdigit():
            return ('num', int(tok))
        elif tok.startswith("'") and tok.endswith("'"):
            return ('num', ord(tok[1]))
        elif re.match(r'^[a-zA-Z_]\w*$', tok):
            if self.peek() == '(':
                self.next()
                args = []
                while self.peek() != ')':
                    args.append(self.parse_expr())
                    if self.peek() == ',':
                        self.next()
                self.expect(')')
                return ('call', tok, args)
            return ('var', tok)
        elif tok == '(':
            expr = self.parse_expr()
            self.expect(')')
            return expr
        else:
            raise ValueError(f"意外的 token: {tok}")

# ===== 代码生成 =====
class CodeGen:
    def __init__(self):
        self.code = []
        self.labels = {}
        self.label_cnt = 0
        self.var_offset = 0
        self.vars = {}

    def new_label(self):
        self.label_cnt += 1
        return f"L{self.label_cnt}"

    def emit(self, mnemonic, *args):
        self.code.append((mnemonic, args))

    def gen_expr(self, expr):
        """生成表达式代码，结果在 R0"""
        if expr[0] == 'num':
            self.emit('MOVI', 'R0', expr[1])
        elif expr[0] == 'var':
            # 从栈帧加载
            off = self.vars.get(expr[1], 0)
            self.emit('LOAD', 'R0', off)
        elif expr[0] == 'binop':
            op = expr[1]
            self.gen_expr(expr[2])
            self.emit('PUSH', 'R0')
            self.gen_expr(expr[3])
            self.emit('POP', 'R1')
            if op == '+':
                self.emit('ADD', 'R1', 'R0')
                self.emit('MOV', 'R0', 'R1')
            elif op == '-':
                self.emit('SUB', 'R1', 'R0')
                self.emit('MOV', 'R0', 'R1')
            elif op == '*':
                self.emit('MUL', 'R1', 'R0')
                self.emit('MOV', 'R0', 'R1')
            elif op == '/':
                self.emit('DIV', 'R1', 'R0')
                self.emit('MOV', 'R0', 'R1')
            elif op == '==':
                self.emit('CMP', 'R0', 'R1')
            elif op == '<':
                self.emit('CMP', 'R1', 'R0')
            elif op == '>':
                self.emit('CMP', 'R0', 'R1')
        elif expr[0] == 'call':
            # 函数调用
            for arg in expr[2]:
                self.gen_expr(arg)
                self.emit('PUSH', 'R0')
            self.emit('CALL', expr[1])
            # 清理参数
            for _ in expr[2]:
                self.emit('POP', 'R1')

    def gen_stmt(self, stmt):
        """生成语句代码"""
        if stmt[0] == 'decl':
            self.gen_expr(stmt[2])
            off = self.var_offset
            self.vars[stmt[1]] = off
            self.var_offset += 1
            self.emit('STORE', 'R0', off)
        elif stmt[0] == 'assign':
            self.gen_expr(stmt[2])
            off = self.vars.get(stmt[1], 0)
            self.emit('STORE', 'R0', off)
        elif stmt[0] == 'if':
            self.gen_expr(stmt[1])
            else_label = self.new_label()
            end_label = self.new_label()
            self.emit('JZ', else_label)
            for s in stmt[2]:
                self.gen_stmt(s)
            self.emit('JMP', end_label)
            self.labels[else_label] = len(self.code)
            if stmt[3]:
                for s in stmt[3]:
                    self.gen_stmt(s)
            self.labels[end_label] = len(self.code)
        elif stmt[0] == 'while':
            start_label = self.new_label()
            end_label = self.new_label()
            self.labels[start_label] = len(self.code)
            self.gen_expr(stmt[1])
            self.emit('JZ', end_label)
            for s in stmt[2]:
                self.gen_stmt(s)
            self.emit('JMP', start_label)
            self.labels[end_label] = len(self.code)
        elif stmt[0] == 'return':
            self.gen_expr(stmt[1])
            self.emit('RET')
        elif stmt[0] == 'call':
            for arg in stmt[2]:
                self.gen_expr(arg)
                self.emit('PUSH', 'R0')
            self.emit('CALL', stmt[1])
            for _ in stmt[2]:
                self.emit('POP', 'R1')

    def gen_function(self, func):
        """生成函数代码"""
        self.code = []
        self.labels = {}
        self.label_cnt = 0
        self.var_offset = 0
        self.vars = {}

        # 函数标签
        func_label = func['name']
        self.labels[func_label] = 0

        # 生成函数体
        for stmt in func['body']:
            self.gen_stmt(stmt)

        # 默认返回
        self.emit('MOVI', 'R0', 0)
        self.emit('RET')

        return self.code, self.labels

# ===== 输出 =====
def output_asm(code, labels):
    lines = []
    for i, (mnemonic, args) in enumerate(code):
        # 查找标签
        for label, addr in labels.items():
            if addr == i:
                lines.append(f"{label}:")
        # 指令
        args_str = ', '.join(str(a) for a in args)
        lines.append(f"    {mnemonic} {args_str}")
    return '\n'.join(lines)

# ===== 入口 =====
if __name__ == '__main__':
    if len(sys.argv) < 2:
        print("用法: cc.py <源文件.c>")
        sys.exit(1)

    with open(sys.argv[1], 'r') as f:
        source = f.read()

    tokens = tokenize(source)
    parser = Parser(tokens)
    funcs = parser.parse()

    for func in funcs:
        cg = CodeGen()
        code, labels = cg.gen_function(func)
        print(f"; 函数: {func['name']}")
        print(output_asm(code, labels))
        print()
