**三、操作系统内核**

一个极简多任务内核，跑在你的 CPU 上。

```c
// os.c - 你的操作系统内核

// ===== 系统调用号 =====
#define SYS_WRITE   1
#define SYS_READ    2
#define SYS_FORK    3
#define SYS_EXIT    4
#define SYS_WAIT    5
#define SYS_OPEN    6
#define SYS_CLOSE   7
#define SYS_SBRK    8

// ===== 任务控制块 =====
struct task {
    int pid;                // 进程 ID
    int state;              // 0=就绪, 1=运行, 2=阻塞, 3=僵尸
    int pc;                 // 程序计数器
    int sp;                 // 栈指针
    int regs[16];           // 通用寄存器
    int fregs[16];          // 浮点寄存器
    int page_table;         // 页表基址
    int parent;             // 父进程 PID
    int exit_code;          // 退出码
};

struct task tasks[4];       // 最多 4 个任务
int current_task = 0;       // 当前任务
int next_pid = 1;           // 下一个 PID

// ===== 初始化 =====
void os_init() {
    // 初始化任务表
    for (int i = 0; i < 4; i++) {
        tasks[i].pid = 0;
        tasks[i].state = 3;
        tasks[i].parent = 0;
    }

    // 创建 init 进程
    tasks[0].pid = next_pid++;
    tasks[0].state = 0;
    tasks[0].pc = 0x100;    // init 程序入口
    tasks[0].sp = 0xFF;
    tasks[0].parent = 0;

    // 设置定时器
    TIMER(0, 100);          // 定时器 0，周期 100
    TIMERSTART(0);
    SEI();                  // 开中断
}

// ===== 调度器 =====
void schedule() {
    // 保存当前任务
    tasks[current_task].pc = CSRR(0);  // 读 PC
    tasks[current_task].sp = CSRR(1);  // 读 SP

    // 找下一个就绪任务
    int next = (current_task + 1) % 4;
    while (tasks[next].state != 0) {
        next = (next + 1) % 4;
        if (next == current_task) {
            // 没有其他任务，继续当前任务
            return;
        }
    }

    // 切换
    current_task = next;
    tasks[current_task].state = 1;

    // 恢复新任务
    CSRW(0, tasks[current_task].pc);
    CSRW(1, tasks[current_task].sp);
}

// ===== 系统调用处理 =====
void syscall_handler() {
    int syscall_num = CSRR(6);  // 读系统调用号

    switch (syscall_num) {
        case SYS_WRITE:
            // 写文件描述符
            OUT(CSRR(0));  // 输出到 LED
            break;

        case SYS_READ:
            // 读文件描述符
            break;

        case SYS_FORK:
            // 创建新进程
            if (next_pid < 4) {
                int child = current_task + 1;
                tasks[child].pid = next_pid++;
                tasks[child].state = 0;
                tasks[child].pc = tasks[current_task].pc;
                tasks[child].sp = tasks[current_task].sp;
                tasks[child].parent = tasks[current_task].pid;
                // 返回值：子进程返回 0，父进程返回子进程 PID
                return tasks[child].pid;
            }
            return -1;

        case SYS_EXIT:
            // 退出进程
            tasks[current_task].state = 3;  // 僵尸
            tasks[current_task].exit_code = CSRR(0);
            schedule();
            break;

        case SYS_WAIT:
            // 等待子进程
            break;

        case SYS_OPEN:
            // 打开文件
            break;

        case SYS_CLOSE:
            // 关闭文件
            break;

        case SYS_SBRK:
            // 扩展堆
            break;
    }
}

// ===== 中断处理 =====
void irq_handler() {
    int irq = CSRR(5);  // 读中断挂起

    if (irq & 0x01) {
        // 定时器中断 → 调度
        schedule();
    }

    if (irq & 0x02) {
        // 键盘中断
    }

    if (irq & 0x04) {
        // 网络中断
    }
}

// ===== 主函数 =====
void kernel_main() {
    os_init();

    // 创建初始进程
    // 进程 0：LED 计数
    // 进程 1：内存写入
    // 进程 2：浮点运算
    // 进程 3：系统调用

    while (1) {
        // 空闲循环
    }
}
