**四、应用程序**

```c
// app.c - 用户程序

// ===== 系统调用接口 =====
int write(int fd, char* buf, int len) {
    SYSCALL(SYS_WRITE);
    return 0;
}

int fork() {
    SYSCALL(SYS_FORK);
    return 0;
}

void exit(int code) {
    SYSCALL(SYS_EXIT);
}

// ===== 主程序 =====
int main() {
    int pid = fork();

    if (pid == 0) {
        // 子进程
        while (1) {
            write(1, "child\n", 6);
        }
    } else {
        // 父进程
        while (1) {
            write(1, "parent\n", 7);
        }
    }

    return 0;
}
