**一、完整 C 编译器（Python）**

支持指针、数组、结构体、递归、多函数。

```python
#!/usr/bin/env python3
# cc_full.py - 完整 C 编译器

import sys, re

# ===== 词法分析 =====
KEYWORDS = {'int', 'char', 'void', 'if', 'else', 'while', 'for',
            'return', 'struct', 'sizeof', 'break', 'continue'}

def tokenize(source):
    tokens = []
    for line in source.split('\n'):
        line = re.sub(r'//.*$', '', line).strip()
        if not line:
            continue
        # 字符串
        for m in re.finditer(r'"([^"]*)"', line):
            tokens.append(('STR', m.group(1)))
        line = re.sub(r'"[^"]*"', '""', line)
        # 分割
        for tok in re.findall(r'[a-zA-Z_]\w*|\d+|[-+*/%=<>!&|^~(){}\[\];,.:]|"[^"]*"', line):
            if tok in KEYWORDS:
                tokens.append(('KW', tok))
            elif tok.isdigit():
                tokens.append(('NUM', int(tok)))
            elif re.match(r'^[a-zA-Z_]\w*$', tok):
                tokens.append(('ID', tok))
            else:
                tokens.append(('OP', tok))
    return tokens

# ===== 语法树 =====
class Node:
    def __init__(self, kind, **kwargs):
        self.kind = kind
        self.__dict__.update(kwargs)

# ===== 语法分析 =====
class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0
        self.structs = {}

    def peek(self, offset=0):
        idx = self.pos + offset
        return self.tokens[idx] if idx < len(self.tokens) else ('EOF', None)

    def next(self):
        tok = self.peek()
        self.pos += 1
        return tok

    def expect(self, kind, val=None):
        t = self.next()
        if t[0] != kind or (val and t[1] != val):
            raise ValueError(f"期望 {kind} {val}，得到 {t}")
        return t

    def parse(self):
        funcs = []
        while self.peek()[0] != 'EOF':
            funcs.append(self.parse_function())
        return funcs

    def parse_type(self):
        """解析类型：int, char, void, struct xxx"""
        t = self.next()
        if t == ('KW', 'struct'):
            name = self.next()[1]
            return ('struct', name)
        return ('base', t[1])

    def parse_function(self):
        ret_type = self.parse_type()
        name = self.next()[1]
        self.expect('OP', '(')
        params = []
        while self.peek() != ('OP', ')'):
            ptype = self.parse_type()
            pname = self.next()[1]
            params.append((ptype, pname))
            if self.peek() == ('OP', ','):
                self.next()
        self.expect('OP', ')')
        self.expect('OP', '{')
        body = self.parse_block()
        self.expect('OP', '}')
        return Node('func', ret=ret_type, name=name, params=params, body=body)

    def parse_block(self):
        stmts = []
        while self.peek() != ('OP', '}'):
            stmts.append(self.parse_statement())
        return stmts

    def parse_statement(self):
        t = self.peek()

        # 声明
        if t == ('KW', 'int') or t == ('KW', 'char') or t == ('KW', 'void') or t == ('KW', 'struct'):
            return self.parse_decl()

        # if
        if t == ('KW', 'if'):
            self.next()
            self.expect('OP', '(')
            cond = self.parse_expr()
            self.expect('OP', ')')
            self.expect('OP', '{')
            then = self.parse_block()
            self.expect('OP', '}')
            els = None
            if self.peek() == ('KW', 'else'):
                self.next()
                self.expect('OP', '{')
                els = self.parse_block()
                self.expect('OP', '}')
            return Node('if', cond=cond, then=then, els=els)

        # while
        if t == ('KW', 'while'):
            self.next()
            self.expect('OP', '(')
            cond = self.parse_expr()
            self.expect('OP', ')')
            self.expect('OP', '{')
            body = self.parse_block()
            self.expect('OP', '}')
            return Node('while', cond=cond, body=body)

        # for
        if t == ('KW', 'for'):
            self.next()
            self.expect('OP', '(')
            init = self.parse_statement()
            cond = self.parse_expr()
            self.expect('OP', ';')
            step = self.parse_statement()
            self.expect('OP', ')')
            self.expect('OP', '{')
            body = self.parse_block()
            self.expect('OP', '}')
            return Node('for', init=init, cond=cond, step=step, body=body)

        # return
        if t == ('KW', 'return'):
            self.next()
            expr = self.parse_expr()
            self.expect('OP', ';')
            return Node('return', expr=expr)

        # break / continue
        if t == ('KW', 'break'):
            self.next(); self.expect('OP', ';')
            return Node('break')
        if t == ('KW', 'continue'):
            self.next(); self.expect('OP', ';')
            return Node('continue')

        # 表达式语句
        expr = self.parse_expr()
        self.expect('OP', ';')
        return Node('expr_stmt', expr=expr)

    def parse_decl(self):
        typ = self.parse_type()
        name = self.next()[1]
        # 数组
        if self.peek() == ('OP', '['):
            self.next()
            size = self.parse_expr()
            self.expect('OP', ']')
            self.expect('OP', ';')
            return Node('decl', typ=typ, name=name, size=size)
        # 初始化
        if self.peek() == ('OP', '='):
            self.next()
            init = self.parse_expr()
            self.expect('OP', ';')
            return Node('decl', typ=typ, name=name, init=init)
        self.expect('OP', ';')
        return Node('decl', typ=typ, name=name)

    def parse_expr(self):
        return self.parse_assign()

    def parse_assign(self):
        left = self.parse_or()
        if self.peek() == ('OP', '='):
            self.next()
            right = self.parse_assign()
            return Node('assign', left=left, right=right)
        return left

    def parse_or(self):
        left = self.parse_and()
        while self.peek() == ('OP', '||'):
            self.next()
            right = self.parse_and()
            left = Node('binop', op='||', left=left, right=right)
        return left

    def parse_and(self):
        left = self.parse_eq()
        while self.peek() == ('OP', '&&'):
            self.next()
            right = self.parse_eq()
            left = Node('binop', op='&&', left=left, right=right)
        return left

    def parse_eq(self):
        left = self.parse_rel()
        while self.peek()[0] == 'OP' and self.peek()[1] in ('==', '!='):
            op = self.next()[1]
            right = self.parse_rel()
            left = Node('binop', op=op, left=left, right=right)
        return left

    def parse_rel(self):
        left = self.parse_add()
        while self.peek()[0] == 'OP' and self.peek()[1] in ('<', '>', '<=', '>='):
            op = self.next()[1]
            right = self.parse_add()
            left = Node('binop', op=op, left=left, right=right)
        return left

    def parse_add(self):
        left = self.parse_mul()
        while self.peek()[0] == 'OP' and self.peek()[1] in ('+', '-'):
            op = self.next()[1]
            right = self.parse_mul()
            left = Node('binop', op=op, left=left, right=right)
        return left

    def parse_mul(self):
        left = self.parse_unary()
        while self.peek()[0] == 'OP' and self.peek()[1] in ('*', '/', '%'):
            op = self.next()[1]
            right = self.parse_unary()
            left = Node('binop', op=op, left=left, right=right)
        return left

    def parse_unary(self):
        t = self.peek()
        if t == ('OP', '-'):
            self.next()
            return Node('unary', op='-', expr=self.parse_unary())
        if t == ('OP', '!'):
            self.next()
            return Node('unary', op='!', expr=self.parse_unary())
        if t == ('OP', '&'):
            self.next()
            return Node('addr', expr=self.parse_unary())
        if t == ('OP', '*'):
            self.next()
            return Node('deref', expr=self.parse_unary())
        if t == ('KW', 'sizeof'):
            self.next()
            self.expect('OP', '(')
            typ = self.parse_type()
            self.expect('OP', ')')
            return Node('sizeof', typ=typ)
        return self.parse_postfix()

    def parse_postfix(self):
        expr = self.parse_primary()
        while True:
            t = self.peek()
            if t == ('OP', '['):
                self.next()
                idx = self.parse_expr()
                self.expect('OP', ']')
                expr = Node('index', arr=expr, idx=idx)
            elif t == ('OP', '('):
                self.next()
                args = []
                while self.peek() != ('OP', ')'):
                    args.append(self.parse_expr())
                    if self.peek() == ('OP', ','):
                        self.next()
                self.expect('OP', ')')
                expr = Node('call', func=expr, args=args)
            elif t == ('OP', '.'):
                self.next()
                field = self.next()[1]
                expr = Node('field', obj=expr, name=field)
            else:
                break
        return expr

    def parse_primary(self):
        t = self.next()
        if t[0] == 'NUM':
            return Node('num', val=t[1])
        if t[0] == 'STR':
            return Node('str', val=t[1])
        if t[0] == 'ID':
            return Node('var', name=t[1])
        if t == ('OP', '('):
            expr = self.parse_expr()
            self.expect('OP', ')')
            return expr
        raise ValueError(f"意外的 token: {t}")

# ===== 代码生成 =====
class CodeGen:
    def __init__(self, structs):
        self.code = []
        self.labels = {}
        self.label_cnt = 0
        self.vars = {}       # 局部变量 → 栈偏移
        self.var_offset = 0
        self.structs = structs
        self.strings = []
        self.break_labels = []
        self.continue_labels = []

    def new_label(self):
        self.label_cnt += 1
        return f"L{self.label_cnt}"

    def emit(self, mnemonic, *args):
        self.code.append((mnemonic, args))

    def alloc_var(self, name):
        off = self.var_offset
        self.vars[name] = off
        self.var_offset += 1
        return off

    def gen_expr(self, expr):
        if expr.kind == 'num':
            self.emit('MOVI', 'R0', expr.val)
        elif expr.kind == 'str':
            idx = len(self.strings)
            self.strings.append(expr.val)
            self.emit('MOVI', 'R0', 0x80 + idx)
        elif expr.kind == 'var':
            off = self.vars.get(expr.name, 0)
            self.emit('LOAD', 'R0', off)
        elif expr.kind == 'assign':
            self.gen_expr(expr.right)
            if expr.left.kind == 'var':
                off = self.vars.get(expr.left.name, 0)
                self.emit('STORE', 'R0', off)
            elif expr.left.kind == 'deref':
                self.emit('PUSH', 'R0')
                self.gen_expr(expr.left.expr)
                self.emit('MOV', 'R1', 'R0')
                self.emit('POP', 'R0')
                self.emit('STORER', 'R0', 'R1')
        elif expr.kind == 'binop':
            op = expr.op
            self.gen_expr(expr.left)
            self.emit('PUSH', 'R0')
            self.gen_expr(expr.right)
            self.emit('POP', 'R1')
            if op == '+':    self.emit('ADD', 'R0', 'R1')
            elif op == '-':  self.emit('SUB', 'R1', 'R0'); self.emit('MOV', 'R0', 'R1')
            elif op == '*':  self.emit('MUL', 'R1', 'R0'); self.emit('MOV', 'R0', 'R1')
            elif op == '/':  self.emit('DIV', 'R1', 'R0'); self.emit('MOV', 'R0', 'R1')
            elif op == '%':  self.emit('MOD', 'R1', 'R0'); self.emit('MOV', 'R0', 'R1')
            elif op == '==': self.emit('CMP', 'R0', 'R1')
            elif op == '!=': self.emit('CMP', 'R0', 'R1'); self.emit('XORI', 'R0', 1)
            elif op == '<':  self.emit('CMP', 'R1', 'R0')
            elif op == '>':  self.emit('CMP', 'R0', 'R1')
            elif op == '<=': self.emit('CMP', 'R0', 'R1'); self.emit('XORI', 'R0', 1)
            elif op == '>=': self.emit('CMP', 'R1', 'R0'); self.emit('XORI', 'R0', 1)
            elif op == '&&': self.emit('AND', 'R0', 'R1')
            elif op == '||': self.emit('OR', 'R0', 'R1')
        elif expr.kind == 'unary':
            self.gen_expr(expr.expr)
            if expr.op == '-':
                self.emit('MOVI', 'R1', 0)
                self.emit('SUB', 'R1', 'R0')
                self.emit('MOV', 'R0', 'R1')
            elif expr.op == '!':
                self.emit('MOVI', 'R1', 1)
                self.emit('XOR', 'R0', 'R1')
        elif expr.kind == 'addr':
            if expr.expr.kind == 'var':
                off = self.vars.get(expr.expr.name, 0)
                self.emit('MOVI', 'R0', off)
            elif expr.expr.kind == 'index':
                self.gen_expr(expr.expr.arr)
                self.emit('PUSH', 'R0')
                self.gen_expr(expr.expr.idx)
                self.emit('POP', 'R1')
                self.emit('ADD', 'R0', 'R1')
        elif expr.kind == 'deref':
            self.gen_expr(expr.expr)
            self.emit('MOV', 'R1', 'R0')
            self.emit('LOADR', 'R0', 'R1')
        elif expr.kind == 'index':
            self.gen_expr(expr.arr)
            self.emit('PUSH', 'R0')
            self.gen_expr(expr.idx)
            self.emit('POP', 'R1')
            self.emit('ADD', 'R0', 'R1')
            self.emit('MOV', 'R1', 'R0')
            self.emit('LOADR', 'R0', 'R1')
        elif expr.kind == 'call':
            for arg in expr.args:
                self.gen_expr(arg)
                self.emit('PUSH', 'R0')
            if expr.func.kind == 'var':
                self.emit('CALL', expr.func.name)
            for _ in expr.args:
                self.emit('POP', 'R1')
        elif expr.kind == 'sizeof':
            self.emit('MOVI', 'R0', 1)  # 简化：所有类型 1 字节
        elif expr.kind == 'field':
            self.gen_expr(expr.obj)
            # 简化：字段偏移由结构体定义决定
            off = self.structs.get(expr.name, 0)
            self.emit('ADDI', 'R0', off)
            self.emit('MOV', 'R1', 'R0')
            self.emit('LOADR', 'R0', 'R1')

    def gen_stmt(self, stmt):
        if stmt.kind == 'decl':
            if hasattr(stmt, 'size'):
                # 数组
                off = self.var_offset
                self.vars[stmt.name] = off
                self.var_offset += 8
                self.emit('MOVI', 'R0', off)
                self.emit('STORE', 'R0', off)
            elif hasattr(stmt, 'init'):
                self.gen_expr(stmt.init)
                off = self.alloc_var(stmt.name)
                self.emit('STORE', 'R0', off)
            else:
                off = self.alloc_var(stmt.name)
                self.emit('MOVI', 'R0', 0)
                self.emit('STORE', 'R0', off)
        elif stmt.kind == 'expr_stmt':
            self.gen_expr(stmt.expr)
        elif stmt.kind == 'if':
            self.gen_expr(stmt.cond)
            else_label = self.new_label()
            end_label = self.new_label()
            self.emit('JZ', else_label)
            for s in stmt.then:
                self.gen_stmt(s)
            self.emit('JMP', end_label)
            self.labels[else_label] = len(self.code)
            if stmt.els:
                for s in stmt.els:
                    self.gen_stmt(s)
            self.labels[end_label] = len(self.code)
        elif stmt.kind == 'while':
            start = self.new_label()
            end = self.new_label()
            self.labels[start] = len(self.code)
            self.gen_expr(stmt.cond)
            self.emit('JZ', end)
            self.break_labels.append(end)
            self.continue_labels.append(start)
            for s in stmt.body:
                self.gen_stmt(s)
            self.break_labels.pop()
            self.continue_labels.pop()
            self.emit('JMP', start)
            self.labels[end] = len(self.code)
        elif stmt.kind == 'for':
            self.gen_stmt(stmt.init)
            start = self.new_label()
            end = self.new_label()
            self.labels[start] = len(self.code)
            self.gen_expr(stmt.cond)
            self.emit('JZ', end)
            self.break_labels.append(end)
            self.continue_labels.append(start)
            for s in stmt.body:
                self.gen_stmt(s)
            self.break_labels.pop()
            self.continue_labels.pop()
            self.gen_stmt(stmt.step)
            self.emit('JMP', start)
            self.labels[end] = len(self.code)
        elif stmt.kind == 'return':
            if stmt.expr:
                self.gen_expr(stmt.expr)
            self.emit('RET')
        elif stmt.kind == 'break':
            if self.break_labels:
                self.emit('JMP', self.break_labels[-1])
        elif stmt.kind == 'continue':
            if self.continue_labels:
                self.emit('JMP', self.continue_labels[-1])

    def gen_function(self, func):
        self.code = []
        self.labels = {}
        self.vars = {}
        self.var_offset = 0
        self.label_cnt = 0
        self.break_labels = []
        self.continue_labels = []

        # 参数
        for ptype, pname in func.params:
            self.alloc_var(pname)

        # 函数体
        for stmt in func.body:
            self.gen_stmt(stmt)

        # 默认返回
        self.emit('MOVI', 'R0', 0)
        self.emit('RET')

        return self.code, self.labels

# ===== 汇编输出 =====
def output_asm(code, labels):
    lines = []
    addr_to_label = {}
    for label, addr in labels.items():
        addr_to_label[addr] = label

    for i, (mnemonic, args) in enumerate(code):
        if i in addr_to_label:
            lines.append(f"{addr_to_label[i]}:")
        args_str = ', '.join(str(a) for a in args)
        lines.append(f"    {mnemonic} {args_str}")
    return '\n'.join(lines)

# ===== 入口 =====
if __name__ == '__main__':
    if len(sys.argv) < 2:
        print("用法: cc_full.py <源文件.c>")
        sys.exit(1)

    with open(sys.argv[1], 'r') as f:
        source = f.read()

    tokens = tokenize(source)
    parser = Parser(tokens)
    funcs = parser.parse()

    for func in funcs:
        cg = CodeGen(parser.structs)
        code, labels = cg.gen_function(func)
        print(f"; 函数: {func.name}")
        print(output_asm(code, labels))
        print()
```

