// libc.c - 你的标准库

// ===== 字符串 =====
int strlen(char* s) {
    int n = 0;
    while (*s != 0) { n++; s++; }
    return n;
}

void strcpy(char* dst, char* src) {
    while (*src != 0) { *dst = *src; dst++; src++; }
    *dst = 0;
}

int strcmp(char* a, char* b) {
    while (*a != 0 && *a == *b) { a++; b++; }
    return *a - *b;
}

// ===== 内存 =====
void* memcpy(void* dst, void* src, int n) {
    char* d = (char*)dst;
    char* s = (char*)src;
    for (int i = 0; i < n; i++) d[i] = s[i];
    return dst;
}

void* memset(void* dst, int val, int n) {
    char* d = (char*)dst;
    for (int i = 0; i < n; i++) d[i] = val;
    return dst;
}

// ===== 堆管理 =====
char heap[256];
int heap_top = 0;

void* malloc(int size) {
    void* p = &heap[heap_top];
    heap_top += size;
    return p;
}

void free(void* p) {
    // 简化：不回收
}

// ===== 输出 =====
void putchar(char c) {
    OUT(c);
}

void print(char* s) {
    while (*s != 0) {
        putchar(*s);
        s++;
    }
}

void print_int(int n) {
    if (n < 0) { putchar('-'); n = -n; }
    if (n >= 10) print_int(n / 10);
    putchar('0' + n % 10);
}

void printf(char* fmt, int a, int b, int c) {
    int arg_idx = 0;
    int args[3];
    args[0] = a; args[1] = b; args[2] = c;
    while (*fmt != 0) {
        if (*fmt == '%') {
            fmt++;
            if (*fmt == 'd') {
                print_int(args[arg_idx]);
                arg_idx++;
            } else if (*fmt == 's') {
                print((char*)args[arg_idx]);
                arg_idx++;
            } else if (*fmt == 'c') {
                putchar(args[arg_idx]);
                arg_idx++;
            }
        } else {
            putchar(*fmt);
        }
        fmt++;
    }
}

// ===== 系统调用 =====
int syscall(int n, int a, int b, int c) {
    // 通过 CSR 传递参数
    CSRW(0, a);
    CSRW(1, b);
    CSRW(2, c);
    SYSCALL(n);
    return CSRR(0);
}

void exit(int code) {
    syscall(4, code, 0, 0);
}

int fork() {
    return syscall(3, 0, 0, 0);
}

int open(char* path) {
    return syscall(6, (int)path, 0, 0);
}

int read(int fd, char* buf, int len) {
    return syscall(2, fd, (int)buf, len);
}

int write(int fd, char* buf, int len) {
    return syscall(1, fd, (int)buf, len);
}

void close(int fd) {
    syscall(7, fd, 0, 0);
}
