    struct dir_entry* e = &root_dir[fd];
    int n = e->size < len ? e->size : len;
    // 从 SD 卡读取
    for (int i = 0; i < n; i++) {
        buf[i] = sd_read_byte(e->start * SECTOR_SIZE + i);
    }
    return n;
}

// 写入文件
int fs_write(int fd, char* buf, int len) {
    if (fd < 0 || fd >= file_count) return -1;
    struct dir_entry* e = &root_dir[fd];
    for (int i = 0; i < len; i++) {
        sd_write_byte(e->start * SECTOR_SIZE + i, buf[i]);
    }
    e->size = len;
    return len;
}

// 创建文件
int fs_create(char* name, int size) {
    if (file_count >= MAX_FILES) return -1;
    struct dir_entry* e = &root_dir[file_count];
    strcpy(e->name, name);
    e->start = file_count * 4 + 100;  // 简化的扇区分配
    e->size = 0;
    e->attr = 0;
    file_count++;
    return file_count - 1;
}

// 删除文件
int fs_delete(char* name) {
    for (int i = 0; i < file_count; i++) {
        if (strcmp(root_dir[i].name, name) == 0) {
            for (int j = i; j < file_count - 1; j++) {
                root_dir[j] = root_dir[j + 1];
            }
            file_count--;
            return 0;
        }
    }
    return -1;
}
