```c
// gfx.c - 图形库

#define SCREEN_W 320
#define SCREEN_H 240
#define FB_BASE  0x1000

// 画点
void gfx_pixel(int x, int y, char color) {
    if (x < 0 || x >= SCREEN_W || y < 0 || y >= SCREEN_H) return;
    int addr = FB_BASE + y * SCREEN_W + x;
    STORE(color, addr);
}

// 画线（Bresenham）
void gfx_line(int x0, int y0, int x1, int y1, char color) {
    int dx = x1 - x0;
    int dy = y1 - y0;
    int sx = dx > 0 ? 1 : -1;
    int sy = dy > 0 ? 1 : -1;
    if (dx < 0) dx = -dx;
    if (dy < 0) dy = -dy;
    int err = dx - dy;

    while (1) {
        gfx_pixel(x0, y0, color);
        if (x0 == x1 && y0 == y1) break;
        int e2 = 2 * err;
        if (e2 > -dy) { err -= dy; x0 += sx; }
        if (e2 < dx)  { err += dx; y0 += sy; }
    }
}

// 画矩形
void gfx_rect(int x, int y, int w, int h, char color) {
    for (int i = 0; i < w; i++) {
        gfx_pixel(x + i, y, color);
        gfx_pixel(x + i, y + h - 1, color);
    }
    for (int i = 0; i < h; i++) {
        gfx_pixel(x, y + i, color);
        gfx_pixel(x + w - 1, y + i, color);
    }
}

// 填充矩形
void gfx_fill_rect(int x, int y, int w, int h, char color) {
    for (int j = 0; j < h; j++) {
        for (int i = 0; i < w; i++) {
            gfx_pixel(x + i, y + j, color);
        }
    }
}

// 画圆（中点圆算法）
void gfx_circle(int cx, int cy, int r, char color) {
    int x = 0, y = r;
    int d = 3 - 2 * r;
    while (x <= y) {
        gfx_pixel(cx + x, cy + y, color);
        gfx_pixel(cx - x, cy + y, color);
        gfx_pixel(cx + x, cy - y, color);
        gfx_pixel(cx - x, cy - y, color);
        gfx_pixel(cx + y, cy + x, color);
        gfx_pixel(cx - y, cy + x, color);
        gfx_pixel(cx + y, cy - x, color);
        gfx_pixel(cx - y, cy - x, color);
        if (d < 0) {
            d = d + 4 * x + 6;
        } else {
            d = d + 4 * (x - y) + 10;
            y--;
        }
        x++;
    }
}

// 清屏
void gfx_clear(char color) {
    for (int i = 0; i < SCREEN_W * SCREEN_H; i++) {
        STORE(color, FB_BASE + i);
    }
}

// 显示字符（8×8 字库）
char font[96][8] = {
    // ... 字库数据 ...
};

void gfx_char(int x, int y, char c, char color) {
    if (c < 32 || c > 127) return;
    for (int j = 0; j < 8; j++) {
        char row = font[c - 32][j];
        for (int i = 0; i < 8; i++) {
            if (row & (1 << (7 - i))) {
                gfx_pixel(x + i, y + j, color);
            }
        }
    }
}

void gfx_string(int x, int y, char* s, char color) {
    while (*s) {
        gfx_char(x, y, *s, color);
        x += 8;
        s++;
    }
}
