**一、Python 解释器（基于栈的 VM）**

```c
// py.c - Python 解释器

#define OP_HALT     0
#define OP_PUSH     1
#define OP_POP      2
#define OP_ADD      3
#define OP_SUB      4
#define OP_MUL      5
#define OP_DIV      6
#define OP_MOD      7
#define OP_CMP      8
#define OP_JMP      9
#define OP_JZ       10
#define OP_JNZ      11
#define OP_LOAD     12
#define OP_STORE    13
#define OP_CALL     14
#define OP_RET      15
#define OP_PRINT    16
#define OP_DUP      17
#define OP_SWAP     18
#define OP_LIST     19
#define OP_INDEX    20
#define OP_LEN      21
#define OP_RANGE    22
#define OP_ITER     23
#define OP_NEXT     24

// ===== 值类型 =====
#define VAL_INT    0
#define VAL_STR    1
#define VAL_LIST   2
#define VAL_NONE   3
#define VAL_BOOL   4

struct value {
    int type;
    int int_val;
    char str_val[64];
    int list_start;
    int list_len;
};

struct value stack[256];
int sp = 0;

// ===== 栈操作 =====
void push_int(int v) {
    stack[sp].type = VAL_INT;
    stack[sp].int_val = v;
    sp++;
}

void push_str(char* s) {
    stack[sp].type = VAL_STR;
    strcpy(stack[sp].str_val, s);
    sp++;
}

struct value pop() {
    sp--;
    return stack[sp];
}

// ===== 虚拟机 =====
int locals[16];

void vm_run(int* code, int code_len) {
    int pc = 0;

    while (pc < code_len) {
        int op = code[pc++];

        switch (op) {
            case OP_HALT:
                return;

            case OP_PUSH:
                push_int(code[pc++]);
                break;

            case OP_POP:
                sp--;
                break;

            case OP_ADD: {
                struct value b = pop();
                struct value a = pop();
                push_int(a.int_val + b.int_val);
                break;
            }

            case OP_SUB: {
                struct value b = pop();
                struct value a = pop();
                push_int(a.int_val - b.int_val);
                break;
            }

            case OP_MUL: {
                struct value b = pop();
                struct value a = pop();
                push_int(a.int_val * b.int_val);
                break;
            }

            case OP_DIV: {
                struct value b = pop();
                struct value a = pop();
                push_int(a.int_val / b.int_val);
                break;
            }

            case OP_MOD: {
                struct value b = pop();
                struct value a = pop();
                push_int(a.int_val % b.int_val);
                break;
            }

            case OP_CMP: {
                struct value b = pop();
                struct value a = pop();
                push_int(a.int_val == b.int_val ? 1 : 0);
                break;
            }

            case OP_JMP:
                pc = code[pc];
                break;

            case OP_JZ: {
                struct value v = pop();
                if (v.int_val == 0) pc = code[pc];
                else pc++;
                break;
            }

            case OP_JNZ: {
                struct value v = pop();
                if (v.int_val != 0) pc = code[pc];
                else pc++;
                break;
            }

            case OP_LOAD:
                push_int(locals[code[pc++]]);
                break;

            case OP_STORE: {
                struct value v = pop();
                locals[code[pc++]] = v.int_val;
                break;
            }

            case OP_CALL:
                // 简化：直接调用内置函数
                break;

            case OP_RET:
                return;

            case OP_PRINT: {
                struct value v = pop();
                if (v.type == VAL_INT) print_int(v.int_val);
                else if (v.type == VAL_STR) print(v.str_val);
                break;
            }

            case OP_DUP: {
                struct value v = stack[sp - 1];
                stack[sp++] = v;
                break;
            }

            case OP_LIST: {
                int n = code[pc++];
                stack[sp].type = VAL_LIST;
                stack[sp].list_len = n;
                sp++;
                break;
            }

            case OP_INDEX: {
                struct value idx = pop();
                struct value arr = pop();
                push_int(arr.list_start + idx.int_val);
                break;
            }

            case OP_LEN: {
                struct value v = pop();
                push_int(v.list_len);
                break;
            }

            case OP_RANGE: {
                struct value end = pop();
                push_int(0);
                push_int(end.int_val);
                break;
            }

            case OP_ITER: {
                // 迭代器：栈顶是 [current, end]
                break;
            }

            case OP_NEXT: {
                // 下一个元素
                break;
            }
        }
    }
}

// ===== Python 子集编译器 =====
// 编译 print(1+2) 为字节码
int py_compile_simple() {
    int code[64];
    int n = 0;

    // print(1 + 2)
    code[n++] = OP_PUSH; code[n++] = 1;
    code[n++] = OP_PUSH; code[n++] = 2;
    code[n++] = OP_ADD;
    code[n++] = OP_PRINT;
    code[n++] = OP_HALT;

    return n;
}

// 编译 while 循环
int py_compile_while() {
    int code[64];
    int n = 0;

    // i = 0
    code[n++] = OP_PUSH; code[n++] = 0;
    code[n++] = OP_STORE; code[n++] = 0;

    // while i < 10:
    int loop_start = n;
    code[n++] = OP_LOAD; code[n++] = 0;
    code[n++] = OP_PUSH; code[n++] = 10;
    code[n++] = OP_CMP;
    int jz_pos = n;
    code[n++] = OP_JZ; code[n++] = 0;

    // print(i)
    code[n++] = OP_LOAD; code[n++] = 0;
    code[n++] = OP_PRINT;

    // i = i + 1
    code[n++] = OP_LOAD; code[n++] = 0;
    code[n++] = OP_PUSH; code[n++] = 1;
    code[n++] = OP_ADD;
    code[n++] = OP_STORE; code[n++] = 0;

    // jmp loop_start
    code[n++] = OP_JMP; code[n++] = loop_start;

    // 修正 JZ
    code[jz_pos + 1] = n;

    code[n++] = OP_HALT;

    return n;
}
